predicted_sql:
SELECT p.first_name, p.country_code
FROM players p
WHERE p.player_id IN (
    SELECT m1.winner_id FROM matches m1
    WHERE m1.tourney_name = 'WTA Championships' AND m1.round = 'F'
)
AND p.player_id IN (
    SELECT m2.winner_id FROM matches m2
    WHERE m2.tourney_name = 'Australian Open' AND m2.round = 'F'
);

SELECT cl.CountryCode, cl.Language
FROM countrylanguage cl
WHERE cl.Percentage = (SELECT MAX(c2.Percentage) FROM countrylanguage c2 WHERE c2.CountryCode = cl.CountryCode);

SELECT r.property_type_description
FROM Properties p
JOIN Ref_Property_Types r ON p.property_type_code = r.property_type_code;

SELECT c.course_name, c.course_id
FROM Courses c
WHERE (SELECT COUNT(*) FROM Sections s WHERE s.course_id = c.course_id) < 2;

SELECT c.course_name
FROM Courses c
WHERE c.course_id IN (SELECT sec.course_id FROM Student_Enrolment_Courses sec);
